        return Results.Created($"/todoitems/{todoItem.Id}", new TodoItemDTO(todoItem));
    });

    app.MapPut("/ap/todoitems/{id}", async ([AsParameters] EditTodoItemRequest request) =>
    {
        var todo = await request.Db.Todos.FindAsync(request.Id);

        if (todo is null) return Results.NotFound();

        todo.Name = request.Dto.Name;
        todo.IsComplete = request.Dto.IsComplete;

        await request.Db.SaveChangesAsync();

        return Results.NoContent();
    });

    app.MapDelete("/ap/todoitems/{id}", async ([AsParameters] TodoItemRequest request) =>
    {
        if (await request.Db.Todos.FindAsync(request.Id) is Todo todo)
        {
            request.Db.Todos.Remove(todo);
            await request.Db.SaveChangesAsync();
            return Results.Ok(new TodoItemDTO(todo));
        }

        return Results.NotFound();
    });

The following record types can be used to replace the preceding parameters:

    record TodoItemRequest(int Id, TodoDb Db);
    record CreateTodoItemRequest(TodoItemDTO Dto, TodoDb Db);
    record EditTodoItemRequest(int Id, TodoItemDTO Dto, TodoDb Db);

Using a struct with AsParameters can be more performant than using a record type.

The complete sample code in the AspNetCore.Docs.Samples repository.

Custom Binding

There are three ways to customize parameter binding:

• For route, query, and header binding sources, bind custom types by adding a static TryParse method for the type.

• Control the binding process by implementing a BindAsync method on a type.

• For advanced scenarios, implement the [Microsoft.AspNetCore.Http.IBindableFromHttpContext1](xref:Microsoft.AspNetCore.Http.IBindableFromHttpContext1) interface to provide custom binding logic directly from the HttpContext.

TryParse

TryParse has two APIs:

    public static bool TryParse(string value, out T result);
    public static bool TryParse(string value, IFormatProvider provider, out T result);

The following code displays Point: 12.3, 10.1 with the URI /map?Point=12.3,10.1:

    var builder = WebApplication.CreateBuilder(args);
    var app = builder.Build();

    // GET /map?Point=12.3,10.1
    app.MapGet("/map", (Point point) => $"Point: {point.X}, {point.Y}");

    app.Run();

    public class Point
    {
        public double X { get; set; }
        public double Y { get; set; }

        public static bool TryParse(string? value, IFormatProvider? provider,
                                    out Point? point)
        {
            // Format is "(12.3,10.1)"
            var trimmedValue = value?.TrimStart('(').TrimEnd(')');
            var segments = trimmedValue?.Split(',',
                    StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            if (segments?.Length == 2
                && double.TryParse(segments[0], out var x)
                && double.TryParse(segments[1], out var y))
            {
                point = new Point { X = x, Y = y };
                return true;
            }

            point = null;
            return false;
        }
    }

BindAsync

BindAsync has the following APIs:

    public static ValueTask<T?> BindAsync(HttpContext context, ParameterInfo parameter);
    public static ValueTask<T?> BindAsync(HttpContext context);

The following code displays SortBy:xyz, SortDirection:Desc, CurrentPage:99 with the URI /products?SortBy=xyz&SortDir=Desc&Page=99:

    using System.Reflection;

    var builder = WebApplication.CreateBuilder(args);
    var app = builder.Build();

    // GET /products?SortBy=xyz&SortDir=Desc&Page=99
    app.MapGet("/products", (PagingData pageData) => $"SortBy:{pageData.SortBy}, " +
           $"SortDirection:{pageData.SortDirection}, CurrentPage:{pageData.CurrentPage}");

    app.Run();

    public class PagingData
    {
        public string? SortBy { get; init; }
        public SortDirection SortDirection { get; init; }
        public int CurrentPage { get; init; } = 1;

        public static ValueTask<PagingData?> BindAsync(HttpContext context,
                                                       ParameterInfo parameter)
        {
            const string sortByKey = "sortBy";
            const string sortDirectionKey = "sortDir";
            const string currentPageKey = "page";

            Enum.TryParse<SortDirection>(context.Request.Query[sortDirectionKey],
                                         ignoreCase: true, out var sortDirection);
            int.TryParse(context.Request.Query[currentPageKey], out var page);
            page = page == 0 ? 1 : page;

            var result = new PagingData
            {
                SortBy = context.Request.Query[sortByKey],
                SortDirection = sortDirection,
                CurrentPage = page
            };

            return ValueTask.FromResult<PagingData?>(result);
        }
    }

    public enum SortDirection
    {
        Default,
        Asc,
        Desc
    }

Custom parameter binding with IBindableFromHttpContext

ASP.NET Core provides support for custom parameter binding in Minimal APIs using the [Microsoft.AspNetCore.Http.IBindableFromHttpContext1](xref:Microsoft.AspNetCore.Http.IBindableFromHttpContext1) interface. This interface, introduced with C# 11's static abstract members, allows you to create types that can be bound from an HTTP context directly in route handler parameters.

    public interface IBindableFromHttpContext<TSelf>
        where TSelf : class, IBindableFromHttpContext<TSelf>
    {
        static abstract ValueTask<TSelf?> BindAsync(HttpContext context, ParameterInfo parameter);
    }

By implementing the [Microsoft.AspNetCore.Http.IBindableFromHttpContext1](xref:Microsoft.AspNetCore.Http.IBindableFromHttpContext1), you can create custom types that handle their own binding logic from the HttpContext. When a route handler includes a parameter of this type, the framework automatically calls the static BindAsync method to create the instance:

    using CustomBindingExample;

    var builder = WebApplication.CreateBuilder(args);
    var app = builder.Build();

    app.UseHttpsRedirection();

    app.MapGet("/", () => "Hello, IBindableFromHttpContext example!");

    app.MapGet("/custom-binding", (CustomBoundParameter param) =>
    {
        return $"Value from custom binding: {param.Value}";
    });

    app.MapGet("/combined/{id}", (int id, CustomBoundParameter param) =>
    {
        return $"ID: {id}, Custom Value: {param.Value}";
    });

The following is an example implementation of a custom parameter that binds from an HTTP header:

    using System.Reflection;

    namespace CustomBindingExample;

    public class CustomBoundParameter : IBindableFromHttpContext<CustomBoundParameter>
    {
        public string Value { get; init; } = default!;

        public static ValueTask<CustomBoundParameter?> BindAsync(HttpContext context, ParameterInfo parameter)
        {
            // Custom binding logic here
            // This example reads from a custom header
            var value = context.Request.Headers["X-Custom-Header"].ToString();

            // If no header was provided, you could fall back to a query parameter
            if (string.IsNullOrEmpty(value))
            {
                value = context.Request.Query["customValue"].ToString();
            }

            return ValueTask.FromResult<CustomBoundParameter?>(new CustomBoundParameter
            {
                Value = value
            });
        }
    }

You can also implement validation within your custom binding logic:

    app.MapGet("/validated", (ValidatedParameter param) =>
    {
        if (string.IsNullOrEmpty(param.Value))
        {
            return Results.BadRequest("Value cannot be empty");
        }

        return Results.Ok($"Validated value: {param.Value}");
    });

View or download the sample code (how to download)

Binding failures

When binding fails, the framework logs a debug message and returns various status codes to the client depending on the failure mode.

 Failure mode   Nullable Parameter Type   Binding Source   Status code

 {ParameterType}.TryParse returns false   yes   route/query/header   400

 {ParameterType}.BindAsync returns null   yes   custom   400

 {ParameterType}.BindAsync throws   doesn't matter   custom   500

 Failure to deserialize JSON body   doesn't matter   body   400

 Wrong content type (not application/json)   doesn't matter   body   415

When ThrowOnBadRequest is false, endpoints that have a filter pipeline run their filters after a parameter-check failure (such as failed route, query, or header parsing, or a missing required parameter), allowing a filter to observe the 400 status code and replace the response body. Endpoint filters don't run for body-reading failures (such as malformed JSON or unsupported content types) or for binding exceptions. For more information, see Filters and parameter binding failures.

Binding Precedence

The rules for determining a binding source from a parameter:

• Explicit attribute defined on parameter (From* attributes) in the following order:

• Route values: [FromRoute]

• Query string: [FromQuery]

• Header: [FromHeader]

• Body: [FromBody]

• Form: [FromForm]

• Service: [FromServices]

• Parameter values: [AsParameters]

• Special types

• HttpContext

• HttpRequest (HttpContext.Request)

• HttpResponse (HttpContext.Response)

• ClaimsPrincipal (HttpContext.User)

• CancellationToken (HttpContext.RequestAborted)

• IFormCollection (HttpContext.Request.Form)

• IFormFileCollection (HttpContext.Request.Form.Files)

• IFormFile (HttpContext.Request.Form.Files[paramName])

• Stream (HttpContext.Request.Body)

• PipeReader (HttpContext.Request.BodyReader)

• Parameter type has a valid static BindAsync method.

• Parameter type is a string or has a valid static TryParse method.

• If the parameter name exists in the route template for example, app.Map("/todo/{id}", (int id) => {});, then it's bound from the route.

• Bound from the query string.

• If the parameter type is a service provided by dependency injection, it uses that service as the source.

• The parameter is from the body.

Configure JSON deserialization options for body binding

The body binding source uses System.Text.Json?displayProperty=fullName for deserialization. It is not possible to change this default, but JSON serialization and deserialization options can be configured.

Configure JSON deserialization options globally

Options that apply globally for an app can be configured by invoking Microsoft.Extensions.DependencyInjection.HttpJsonServiceExtensions.ConfigureHttpJsonOptions*. The following example includes public fields and formats JSON output.

    var builder = WebApplication.CreateBuilder(args);

    builder.Services.ConfigureHttpJsonOptions(options => {
        options.SerializerOptions.WriteIndented = true;
        options.SerializerOptions.IncludeFields = true;
    });

    var app = builder.Build();

    app.MapPost("/", (Todo todo) => {
        if (todo is not null) {
            todo.Name = todo.NameField;
        }
        return todo;
    });

    app.Run();

    class Todo {
        public string? Name { get; set; }
        public string? NameField;
        public bool IsComplete { get; set; }
    }
    // If the request body contains the following JSON:
    //
    // {"nameField":"Walk dog", "isComplete":false}
    //
    // The endpoint returns the following JSON:
    //
    // {
    //    "name":"Walk dog",
    //    "nameField":"Walk dog",
    //    "isComplete":false
    // }

Since the sample code configures both serialization and deserialization, it can read NameField and include NameField in the output JSON.

Configure JSON deserialization options for an endpoint

Microsoft.AspNetCore.Http.HttpRequestJsonExtensions.ReadFromJsonAsync* has overloads that accept a System.Text.Json.JsonSerializerOptions object. The following example includes public fields and formats JSON output.

    using System.Text.Json;

    var app = WebApplication.Create();

    var options = new JsonSerializerOptions(JsonSerializerDefaults.Web) {
        IncludeFields = true,
        WriteIndented = true
    };

    app.MapPost("/", async (HttpContext context) => {
        if (context.Request.HasJsonContentType()) {
            var todo = await context.Request.ReadFromJsonAsync<Todo>(options);
            if (todo is not null) {
                todo.Name = todo.NameField;
            }
            return Results.Ok(todo);
        }
        else {
            return Results.BadRequest();
        }
    });

    app.Run();

    class Todo
    {
        public string? Name { get; set; }
        public string? NameField;
        public bool IsComplete { get; set; }
    }
    // If the request body contains the following JSON:
    //
    // {"nameField":"Walk dog", "isComplete":false}
    //
    // The endpoint returns the following JSON:
    //
    // {
    //    "name":"Walk dog",
    //    "isComplete":false
    // }

Since the preceding code applies the customized options only to deserialization, the output JSON excludes NameField.

Read the request body

Read the request body directly using a Microsoft.AspNetCore.Http.HttpContext or Microsoft.AspNetCore.Http.HttpRequest parameter:

    var builder = WebApplication.CreateBuilder(args);
    var app = builder.Build();

    app.MapPost("/uploadstream", async (IConfiguration config, HttpRequest request) =>
    {
        var filePath = Path.Combine(config["StoredFilesPath"], Path.GetRandomFileName());

        await using var writeStream = File.Create(filePath);
        await request.BodyReader.CopyToAsync(writeStream);
    });

    app.Run();

The preceding code:

• Accesses the request body using Microsoft.AspNetCore.Http.HttpRequest.BodyReader?displayProperty=nameWithType.

• Copies the request body to a local file.

How to create responses in Minimal API apps

This article explains how to create responses for Minimal API endpoints in ASP.NET Core. Minimal APIs provide several ways to return data and HTTP status codes.

Minimal endpoints support the following types of return values:

• string - This includes Task<string>, ValueTask<string>, and F# Async<string>.

• T (Any other type) - This includes Task<T>, ValueTask<T>, and F# Async<'T>.

• IResult based - This includes Task<IResult>, ValueTask<IResult>, and F# Async<IResult>.

Note

F# Async<'T> is supported as an awaitable return type in minimal API endpoints. When unit is the generic type argument of a generic awaitable type (Task<unit>, ValueTask<unit>, or Async<unit>), the framework coerces it to void, returning an empty response body instead of the JSON null token.

Important

Starting with ASP.NET Core 10, known API endpoints no longer redirect to login pages when using cookie authentication. Instead, they return 401/403 status codes. For details, see API endpoint authentication behavior in ASP.NET Core.

string return values

 Behavior   Content-Type

 The framework writes the string directly to the response.   text/plain

Consider the following route handler, which returns a Hello world text.

    app.MapGet("/hello", () => "Hello World");

The 200 status code is returned with text/plain Content-Type header and the following content.

    Hello World

T (Any other type) return values

 Behavior   Content-Type

 The framework JSON-serializes the response.   application/json

Consider the following route handler, which returns an anonymous type containing a Message string property.

    app.MapGet("/hello", () => new { Message = "Hello World" });

The 200 status code is returned with application/json Content-Type header and the following content.

    {"message":"Hello World"}

IResult return values

 Behavior   Content-Type

 The framework calls IResult.ExecuteAsync.   Decided by the IResult implementation.

The IResult interface defines a contract that represents the result of an HTTP endpoint. The static Results class and the static TypedResults are used to create various IResult objects that represent different types of responses.

TypedResults versus Results

The Microsoft.AspNetCore.Http.Results and Microsoft.AspNetCore.Http.TypedResults static classes provide similar sets of results helpers. The TypedResults class is the typed equivalent of the Results class. However, the Results helpers' return type is Microsoft.AspNetCore.Http.IResult, while each TypedResults helper's return type is one of the IResult implementation types. The difference means that for Results helpers a conversion is needed when the concrete type is needed, for example, for unit testing. The implementation types are defined in the Microsoft.AspNetCore.Http.HttpResults namespace.

Returning TypedResults rather than Results has the following advantages:

• TypedResults helpers return strongly typed objects, which can improve code readability, unit testing, and reduce the chance of runtime errors.

• The implementation type automatically provides the response type metadata for OpenAPI to describe the endpoint.

Consider the following endpoint, for which a 200 OK status code with the expected JSON response is produced.

    app.MapGet("/hello", () => Results.Ok(new Message() { Text = "Hello World!" }))
        .Produces<Message>();

In order to document this endpoint correctly the extensions method Produces is called. However, it's not necessary to call Produces if TypedResults is used instead of Results, as shown in the following code. TypedResults automatically provides the metadata for the endpoint.

    app.MapGet("/hello2", () => TypedResults.Ok(new Message() { Text = "Hello World!" }));

For more information about describing a response type, see Include OpenAPI metadata in an ASP.NET Core app. For complete setup instructions, see Overview of OpenAPI support in ASP.NET Core API apps.

Note

The .Produces() and .Produces<T>() extension methods are provided by the shared framework and only add endpoint metadata. To generate an OpenAPI document from that metadata, configure an OpenAPI document generator such as Microsoft.AspNetCore.OpenApi, Swashbuckle, or NSwag. For more information, see Overview of OpenAPI support in ASP.NET Core API apps.

For examples on testing result types, see the Test documentation.

Because all methods on Results return IResult in their signature, the compiler automatically infers that as the request delegate return type when returning different results from a single endpoint. TypedResults requires the use of Results<T1, TN> from such delegates.

The following method compiles because both Results.Ok and Results.NotFound are declared as returning IResult, even though the actual concrete types of the objects returned are different:

    app.MapGet("/todoitems/{id}", async (int id, TodoDb db) =>
        await db.Todos.FindAsync(id)
            is Todo todo
                ? Results.Ok(todo)
                : Results.NotFound());

The following method does not compile, because TypedResults.Ok and TypedResults.NotFound are declared as returning different types and the compiler won't attempt to infer the best matching type:

    app.MapGet("/todoitems/{id}", async (int id, TodoDb db) =>
         await db.Todos.FindAsync(id)
         is Todo todo
            ? TypedResults.Ok(todo)
            : TypedResults.NotFound());

To use TypedResults, the return type must be fully declared; when the method is asynchronous, the declaration requires wrapping the return type in a Task<>. Using TypedResults is more verbose, but that's the trade-off for having the type information be statically available and thus capable of self-describing to OpenAPI:

    app.MapGet("/todoitems/{id}", async Task<Results<Ok<Todo>, NotFound>> (int id, TodoDb db) =>
       await db.Todos.FindAsync(id)
        is Todo todo
           ? TypedResults.Ok(todo)
           : TypedResults.NotFound());

Note

When using a method group whose only parameter is HttpContext (for example, static async Task<Results<ContentHttpResult, BadRequest>> MyHandler(HttpContext context)), app.MapGet matches both RequestDelegate and Delegate. Overload resolution selects the Microsoft.AspNetCore.Http.RequestDelegate overload, which discards return values and triggers analyzer warning ASP0016. To ensure the result is executed and written to the response, cast the method group to Delegate (for example, app.MapGet("/route", (Delegate)MyHandler)) or use a lambda.

When using TypedResults with multiple return branches, an explicit union return type such as Results<T1, T2> (or Task<Results<T1, T2>> for async handlers) is required because the compiler cannot infer a common union type.

Results<TResult1, TResultN>

Use Results<TResult1, TResultN> as the endpoint handler return type instead of IResult when:

• Multiple IResult implementation types are returned from the endpoint handler.

• The static TypedResult class is used to create the IResult objects.

This alternative is better than returning IResult because the generic union types automatically retain the endpoint metadata. And since the Results<TResult1, TResultN> union types implement implicit cast operators, the compiler can automatically convert the types specified in the generic arguments to an instance of the union type.

This has the added benefit of providing compile-time checking that a route handler actually only returns the results that it declares it does. Attempting to return a type that isn't declared as one of the generic arguments to Results<> results in a compilation error.

Consider the following endpoint, for which a 400 BadRequest status code is returned when the orderId is greater than 999. Otherwise, it produces a 200 OK with the expected content.

    app.MapGet("/orders/{orderId}", IResult (int orderId)
        => orderId > 999 ? TypedResults.BadRequest() : TypedResults.Ok(new Order(orderId)))
        .Produces(400)
        .Produces<Order>();

In order to document this endpoint correctly the extension method Produces is called. However, since the TypedResults helper automatically includes the metadata for the endpoint, you can return the Results<T1, Tn> union type instead, as shown in the following code.

    app.MapGet("/orders/{orderId}", Results<BadRequest, Ok<Order>> (int orderId)
        => orderId > 999 ? TypedResults.BadRequest() : TypedResults.Ok(new Order(orderId)));

Built-in results

Common result helpers exist in the Microsoft.AspNetCore.Http.Results and Microsoft.AspNetCore.Http.TypedResults static classes. Returning TypedResults is preferred to returning Results. For more information, see TypedResults versus Results.

The following sections demonstrate the usage of the common result helpers.

JSON

    app.MapGet("/hello", () => Results.Json(new { Message = "Hello World" }));

Microsoft.AspNetCore.Http.HttpResponseJsonExtensions.WriteAsJsonAsync* is an alternative way to return JSON:

    app.MapGet("/", (HttpContext context) => context.Response.WriteAsJsonAsync
        (new { Message = "Hello World" }));

Custom Status Code

    app.MapGet("/405", () => Results.StatusCode(405));

Internal Server Error

    app.MapGet("/500", () => Results.InternalServerError("Something went wrong!"));

The preceding example returns a 500 status code.

Problem and ValidationProblem

    app.MapGet("/problem", () =>
    {
        var extensions = new List<KeyValuePair<string, object?>> { new("test", "value") };
        return TypedResults.Problem("This is an error with extensions",
                                                    extensions: extensions);
    });

Customize validation error responses using IProblemDetailsService

Customize error responses from Minimal API validation logic with an Microsoft.AspNetCore.Http.IProblemDetailsService implementation. Register this service in your application's service collection to enable more consistent and user-specific error responses. Support for Minimal API validation was introduced in ASP.NET Core in .NET 10.

To implement custom validation error responses:

• Implement Microsoft.AspNetCore.Http.IProblemDetailsService or use the default implementation

• Register the service in the DI container

• The validation system automatically uses the registered service to format validation error responses

The following example shows how to register and configure the Microsoft.AspNetCore.Http.IProblemDetailsService to customize validation error responses:

    using System.ComponentModel.DataAnnotations;

    var builder = WebApplication.CreateBuilder(args);

    builder.Services.AddProblemDetails(options =>
    {
        options.CustomizeProblemDetails = context =>
        {
            if (context.ProblemDetails.Status == 400)
            {
                context.ProblemDetails.Title = "Validation error occurred";
                context.ProblemDetails.Extensions["support"] = "Contact support@example.com";
                context.ProblemDetails.Extensions["traceId"] = Guid.NewGuid().ToString();
            }
        };
    });

When a validation error occurs, the Microsoft.AspNetCore.Http.IProblemDetailsService will be used to generate the error response, including any customizations added in the CustomizeProblemDetails callback.

For a complete app example, see the Minimal API sample app demonstrating how to customize validation error responses using the Microsoft.AspNetCore.Http.IProblemDetailsService in ASP.NET Core Minimal APIs.

Text

    app.MapGet("/text", () => Results.Text("This is some text"));

Stream

    var builder = WebApplication.CreateBuilder(args);
    var app = builder.Build();

    var proxyClient = new HttpClient();
    app.MapGet("/pokemon", async () =>
    {
        var stream = await proxyClient.GetStreamAsync("http://contoso/pokedex.json");
        // Proxy the response as JSON
        return Results.Stream(stream, "application/json");
    });

    app.Run();

Results.Stream overloads allow access to the underlying HTTP response stream without buffering. The following example uses ImageSharp to return a reduced size of the specified image:

    using SixLabors.ImageSharp;
    using SixLabors.ImageSharp.Formats.Jpeg;
    using SixLabors.ImageSharp.Processing;

    var builder = WebApplication.CreateBuilder(args);

    var app = builder.Build();

    app.MapGet("/process-image/{strImage}", (string strImage, HttpContext http, CancellationToken token) =>
    {
        http.Response.Headers.CacheControl = $"public,max-age={TimeSpan.FromHours(24).TotalSeconds}";
        return Results.Stream(stream => ResizeImageAsync(strImage, stream, token), "image/jpeg");
    });

    async Task ResizeImageAsync(string strImage, Stream stream, CancellationToken token)
    {
        var strPath = $"wwwroot/img/{strImage}";
        using var image = await Image.LoadAsync(strPath, token);
        int width = image.Width / 2;
        int height = image.Height / 2;
        image.Mutate(x =>x.Resize(width, height));
        await image.SaveAsync(stream, JpegFormat.Instance, cancellationToken: token);
    }

The following example streams an image from Azure Blob storage:

    app.MapGet("/stream-image/{containerName}/{blobName}",
        async (string blobName, string containerName, CancellationToken token) =>
    {
        var conStr = builder.Configuration["blogConStr"];
        BlobContainerClient blobContainerClient = new BlobContainerClient(conStr, containerName);
        BlobClient blobClient = blobContainerClient.GetBlobClient(blobName);
        return Results.Stream(await blobClient.OpenReadAsync(cancellationToken: token), "image/jpeg");
    });

The following example streams a video from an Azure Blob:

    // GET /stream-video/videos/earth.mp4
    app.MapGet("/stream-video/{containerName}/{blobName}",
         async (HttpContext http, CancellationToken token, string blobName, string containerName) =>
    {
        var conStr = builder.Configuration["blogConStr"];
        BlobContainerClient blobContainerClient = new BlobContainerClient(conStr, containerName);
        BlobClient blobClient = blobContainerClient.GetBlobClient(blobName);

        var properties = await blobClient.GetPropertiesAsync(cancellationToken: token);

        DateTimeOffset lastModified = properties.Value.LastModified;
        long length = properties.Value.ContentLength;

        long etagHash = lastModified.ToFileTime() ^ length;
        var entityTag = new EntityTagHeaderValue('\"' + Convert.ToString(etagHash, 16) + '\"');

        http.Response.Headers.CacheControl = $"public,max-age={TimeSpan.FromHours(24).TotalSeconds}";

        return Results.Stream(await blobClient.OpenReadAsync(cancellationToken: token),
            contentType: "video/mp4",
            lastModified: lastModified,
            entityTag: entityTag,
            enableRangeProcessing: true);
    });

Server-Sent Events (SSE)

The TypedResults.ServerSentEvents API supports returning a ServerSentEvents result.

Server-Sent Events is a server push technology that allows a server to send a stream of event messages to a client over a single HTTP connection. In .NET, the event messages are represented as SseItem<T> objects, which may contain an event type, an ID, and a data payload of type T.

The TypedResults class has a static method called ServerSentEvents that can be used to return a ServerSentEvents result. The first parameter to this method is an IAsyncEnumerable<SseItem<T>> that represents the stream of event messages to be sent to the client.

The following example illustrates how to use the TypedResults.ServerSentEvents API to return a stream of heart rate events as JSON objects to the client:

    app.MapGet("sse-item", (CancellationToken cancellationToken) =>
    {
        async IAsyncEnumerable<SseItem<int>> GetHeartRate(
            [EnumeratorCancellation] CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested)
            {
                var heartRate = Random.Shared.Next(60, 100);
                yield return new SseItem<int>(heartRate, eventType: "heartRate")
                {
                    ReconnectionInterval = TimeSpan.FromMinutes(1)
                };
                await Task.Delay(2000, cancellationToken);
            }
        }

        return TypedResults.ServerSentEvents(GetHeartRate(cancellationToken));
    });

For more information, see the Minimal API sample app using the TypedResults.ServerSentEvents API to return a stream of heart rate events as string, ServerSentEvents, and JSON objects to the client.

Always return the stream through TypedResults.ServerSentEvents. A handler that returns IAsyncEnumerable<SseItem<T>> directly compiles and runs, but the result is serialized as JSON rather than sent as Server-Sent Events.

The SseItem<T> overload doesn't take an eventType parameter, because each SseItem<T> carries its own event type. To apply a single event name to every message in the stream, pass a plain IAsyncEnumerable<T> and supply eventType.

Redirect

    app.MapGet("/old-path", () => Results.Redirect("/new-path"));

File

    app.MapGet("/download", () => Results.File("myfile.text"));

