Rate limiter samples

The following samples aren't production quality, they're examples on how to use the limiters.

Limiter with OnRejected, RetryAfter, and GlobalLimiter

The following sample:

• Creates a Microsoft.AspNetCore.RateLimiting.RateLimiterOptions.OnRejected?displayProperty=nameWithType callback that's called when a request exceeds the specified limit. retryAfter can be used with the System.Threading.RateLimiting.TokenBucketRateLimiter, Fixed Window Limiter, and Sliding Window Limiter because these algorithms are able to estimate when more permits are added. The System.Threading.RateLimiting.ConcurrencyLimiter has no way of calculating when permits are available.

• Adds the following limiters:

• A SampleRateLimiterPolicy that implements the [Microsoft.AspNetCore.RateLimiting.IRateLimiterPolicy1](xref:Microsoft.AspNetCore.RateLimiting.IRateLimiterPolicy1) interface. The SampleRateLimiterPolicy class is shown later in this article.

• A SlidingWindowLimiter:

• With a partition for each authenticated user.

• One shared partition for all anonymous users.

• A Microsoft.AspNetCore.RateLimiting.RateLimiterOptions.GlobalLimiter that's applied to all requests. The global limiter is executed first, followed by the endpoint-specific limiter, if one exists. The GlobalLimiter creates a partition for each System.Net.IPAddress.

    // <snippet>
    using System.Globalization;
    using System.Net;
    using System.Threading.RateLimiting;
    using Microsoft.AspNetCore.Identity;
    using Microsoft.EntityFrameworkCore;
    using WebRateLimitAuth;
    using WebRateLimitAuth.Data;
    using WebRateLimitAuth.Models;

    var builder = WebApplication.CreateBuilder(args);

    var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ??
        throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
    builder.Services.AddDbContext<ApplicationDbContext>(options =>
        options.UseSqlServer(connectionString));
    builder.Services.AddDatabaseDeveloperPageExceptionFilter();

    builder.Services.AddDefaultIdentity<IdentityUser>(options => options.SignIn.RequireConfirmedAccount = true)
        .AddEntityFrameworkStores<ApplicationDbContext>();

    builder.Services.Configure<MyRateLimitOptions>(
        builder.Configuration.GetSection(MyRateLimitOptions.MyRateLimit));

    builder.Services.AddRazorPages();
    builder.Services.AddControllersWithViews();

    var userPolicyName = "user";
    var helloPolicy = "hello";
    var myOptions = new MyRateLimitOptions();
    builder.Configuration.GetSection(MyRateLimitOptions.MyRateLimit).Bind(myOptions);

    builder.Services.AddRateLimiter(limiterOptions =>
    {
        limiterOptions.OnRejected = (context, cancellationToken) =>
        {
            if (context.Lease.TryGetMetadata(MetadataName.RetryAfter, out var retryAfter))
            {
                context.HttpContext.Response.Headers.RetryAfter =
                    ((int) retryAfter.TotalSeconds).ToString(NumberFormatInfo.InvariantInfo);
            }

            context.HttpContext.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            context.HttpContext.RequestServices.GetService<ILoggerFactory>()?
                .CreateLogger("Microsoft.AspNetCore.RateLimitingMiddleware")
                .LogWarning("OnRejected: {GetUserEndPoint}", GetUserEndPoint(context.HttpContext));

            return new ValueTask();
        };

        limiterOptions.AddPolicy<string, SampleRateLimiterPolicy>(helloPolicy);
        limiterOptions.AddPolicy(userPolicyName, context =>
        {
            var username = "anonymous user";
            if (context.User.Identity?.IsAuthenticated is true)
            {
                username = context.User.Identity.Name;
            }

            return RateLimitPartition.GetSlidingWindowLimiter(username,
                _ => new SlidingWindowRateLimiterOptions
                {
                    PermitLimit = myOptions.PermitLimit,
                    QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
                    QueueLimit = myOptions.QueueLimit,
                    Window = TimeSpan.FromSeconds(myOptions.Window),
                    SegmentsPerWindow = myOptions.SegmentsPerWindow
                });

        });

        limiterOptions.GlobalLimiter = PartitionedRateLimiter.Create<HttpContext, IPAddress>(context =>
        {
            IPAddress? remoteIpAddress = context.Connection.RemoteIpAddress;

            if (!IPAddress.IsLoopback(remoteIpAddress!))
            {
                return RateLimitPartition.GetTokenBucketLimiter
                (remoteIpAddress!, _ =>
                    new TokenBucketRateLimiterOptions
                    {
                        TokenLimit = myOptions.TokenLimit2,
                        QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
                        QueueLimit = myOptions.QueueLimit,
                        ReplenishmentPeriod = TimeSpan.FromSeconds(myOptions.ReplenishmentPeriod),
                        TokensPerPeriod = myOptions.TokensPerPeriod,
                        AutoReplenishment = myOptions.AutoReplenishment
                    });
            }

            return RateLimitPartition.GetNoLimiter(IPAddress.Loopback);
        });
    });

    var app = builder.Build();

    if (app.Environment.IsDevelopment())
    {
        app.UseMigrationsEndPoint();
    }
    else
    {
        app.UseExceptionHandler("/Error");
        app.UseHsts();
    }

    app.UseHttpsRedirection();
    app.UseStaticFiles();

    app.UseRouting();

    app.UseAuthentication();
    app.UseRateLimiter(); // important to add after UseAuthentication because the limiter uses auth info
    app.UseAuthorization();

    app.MapRazorPages().RequireRateLimiting(userPolicyName);
    app.MapDefaultControllerRoute();

    static string GetUserEndPoint(HttpContext context) =>
       $"User {context.User.Identity?.Name ?? "Anonymous"} endpoint:{context.Request.Path}"
       + $" {context.Connection.RemoteIpAddress}";
    static string GetTicks() => (DateTime.Now.Ticks & 0x11111).ToString("00000");

    app.MapGet("/a", (HttpContext context) => $"{GetUserEndPoint(context)} {GetTicks()}")
        .RequireRateLimiting(userPolicyName);

    app.MapGet("/b", (HttpContext context) => $"{GetUserEndPoint(context)} {GetTicks()}")
        .RequireRateLimiting(helloPolicy);

    app.MapGet("/c", (HttpContext context) => $"{GetUserEndPoint(context)} {GetTicks()}");

    app.Run();
    // </snippet>

Warning

Creating partitions on client IP addresses makes the app vulnerable to Denial of Service Attacks which employ IP Source Address Spoofing. For more information, see BCP 38 RFC 2827 Network Ingress Filtering: Defeating Denial of Service Attacks which employ IP Source Address Spoofing.

