Replace or append MIME types with the ResponseCompressionOptions.MimeTypes property. Wildcard MIME types such as text/* aren't supported. The sample app adds a MIME type for image/svg+xml and compresses and serves the ASP.NET Core banner image banner.svg.

    using Microsoft.AspNetCore.ResponseCompression;
    using ResponseCompressionSample;

    var builder = WebApplication.CreateBuilder(args);

    builder.Services.AddResponseCompression(options =>
    {
        options.EnableForHttps = true;
