          <button id="btnSend">Send</button>
        </div>
      </body>
    </html>

• css/main.css, which provides CSS styles for the homepage:

    *,
    *::before,
    *::after {
      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      padding: 0;
    }

